mapper.select:
SELECT * FROM SETTLEMENT


        AND status = #{status}


        AND (target_id LIKE CONCAT('%', #{searchKeyword}, '%')) 


ORDER BY settlement_deadline ASC
LIMIT #{limit} OFFSET #{offset}

SELECT p.id, p.payment_date, p.payment_price, p.payment_fee, p.gym_id, g.name as gym_name, p.trainer_id, u.name as trainer_name FROM PAYMENT p LEFT JOIN GYM g ON p.gym_id = g.id LEFT JOIN TRAINER t ON p.trainer_id = t.id LEFT JOIN USER u ON p.user_id = u.id WHERE p.status = '결제완료'
AND p.payment_date BETWEEN #{startDate} AND #{endDate}
ORDER BY p.payment_date DESC LIMIT #{limit} OFFSET #{offset}

SELECT p.* FROM PAYMENT p
LEFT JOIN TOSS T on p.user_id = t.user_id


        AND p.status = #{status}


        AND (p.user_id LIKE CONCAT('%', #{searchKeyword}, '%') OR t.order_id LIKE CONCAT('%', #{searchKeyword}, '%'))


ORDER BY p.payment_date DESC
LIMIT #{limit} OFFSET #{offset}
